//! Raw bindings to NVIDIA's SMLib B-rep kernel (USD BRep), through the C shim
//! in `shim/shim.h`. The `smlib` crate wraps them in a safe API.
//!
//! The kernel is not thread-safe: call [`sm_context_create`] once, then make
//! every call from one thread.
//!
//! `bindings.rs` is generated by bindgen from `shim.h` and committed, so
//! builds don't need libclang. After changing `shim.h`, rebuild with
//! `--features regenerate-bindings`.

#![no_std]

#[allow(
    non_camel_case_types,
    non_upper_case_globals,
    missing_docs,
    clippy::all
)]
mod bindings;

pub use bindings::*;
